{
  "implementation": "def solve(case):
    attempts = case['attempts']
    max_attempts = case['max_attempts']
    n = len(attempts)
    if n == 0:
        return {
            'decision': 'retry',
            'next_attempt': 1,
            'memory_append': None
        }
    last = attempts[-1]
    if last['success']:
        return {
            'decision': 'stop',
            'next_attempt': n,
            'memory_append': None
        }
    if n >= max_attempts:
        return {
            'decision': 'stop',
            'next_attempt': n,
            'memory_append': None
        }
    prior_signatures = [a['failure_signature'] for a in attempts[:-1]]
    if last['failure_signature'] in prior_signatures:
        return {
            'decision': 'stop',
            'next_attempt': n,
            'memory_append': None
        }
    return {
        'decision': 'retry',
        'next_attempt': n + 1,
        'memory_append': {
            'reflection': last['reflection'],
            'signature': last['failure_signature']
        }
    }"
}
